import assert from 'node:assert/strict';
import { validatePreparedTaskGraph as beforeValidation } from './baseline-graph-validation.ts';
import { validatePreparedTaskGraph as afterValidation } from '/workspace/vibe-check/src/project-run/task-scheduler/graph-validation.ts';
import { applyForcedBlockedSettlement as beforeBlock } from './baseline-task-lifecycle.ts';
import { applyForcedBlockedSettlement as afterBlock } from '/workspace/vibe-check/src/project-run/task-scheduler/scheduler-task-lifecycle.ts';
import { SchedulerPerformanceIntegrals as BeforeIntegrals } from './baseline-integrals.ts';
import { SchedulerPerformanceIntegrals as AfterIntegrals } from '/workspace/vibe-check/src/project-run/task-scheduler/measurement/integrals.ts';
import { learnedSelectionLayers as beforeLayers } from './baseline-selection-layers.ts';
import { createLearnedSelectionGraph, learnedSelectionLayers as afterLayers, firstCandidateBy } from '/workspace/vibe-check/src/package-tools/learned-critical-path/selection-layers.ts';
import { staticDecision as beforeFallback } from './baseline-static-decision.ts';
import { createStaticDecision } from '/workspace/vibe-check/src/package-tools/learned-critical-path/static-decision.ts';
import { prepareTaskGraph } from '/workspace/vibe-check/src/project-run/task-scheduler/graph.ts';
import { createSchedulerState } from '/workspace/vibe-check/src/project-run/task-scheduler/execution-state.ts';
function countedMap(map: Map<any,any>, count:()=>void) {
 return new Proxy(map,{get(target,key){if(key==='get')return (id:any)=>{count();return target.get(id)};const value=Reflect.get(target,key);return typeof value==='function'?value.bind(target):value}});
}
const result:any[]=[];
for(const n of [16,32,64,128]) {
 const graph=prepareTaskGraph({tasks:Array.from({length:n},(_,i)=>({id:`t${i}`,scopeId:'s',observes:i?[`t${i-1}`]:[]})),scopes:[{id:'s',maxParallel:1,activationTaskIds:['t0'],terminalTaskId:`t${n-1}`} ]},1);
 const counts=[];
 for(const validate of [beforeValidation,afterValidation]) {let gets=0;validate({...graph,rootMaxParallel:1,scopeById:new Map(graph.scopes.map(s=>[s.id,s])),taskById:countedMap(new Map(graph.tasks.map(t=>[t.id,t])),()=>gets++)});counts.push(gets)}
 result.push({candidate:'R04 sparse scope',n,before:counts[0],after:counts[1],unit:'taskById.get'});
 const blocks=[];
 for(const [i,apply] of [beforeBlock,afterBlock].entries()) {let visits=0;const state=createSchedulerState(graph,{execute:()=>0,maxParallel:1});const pending=i===0?new Proxy([...graph.tasks],{get(target,key,receiver){if(typeof key==='string'&&/^\d+$/.test(key))visits++;return Reflect.get(target,key,receiver)}}):countedMap(state.pending,()=>visits++);const shell={...state,pending};for(const t of [...graph.tasks].reverse())apply(shell as any,t.id,[]);assert.equal(shell.settlementsByTaskId.size,n);blocks.push(visits)}
 result.push({candidate:'Shell reverse pending removals',n,before:blocks[0],after:blocks[1],unit:'array indexed visits / Map.get'});
 for(const stage of ['install','interval']) {
 const reads=[];for(const Integrals of [BeforeIntegrals,AfterIntegrals]){let kindReads=0;const pendingTasks=Array.from({length:n},(_,i)=>({taskId:`t${i}`,get kind(){kindReads++;return ['mutex-blocked','capacity-blocked','admissible-pending'][i%3] as any}}));const integrals=new Integrals();integrals.installPendingProjection(pendingTasks,true);if(stage==='interval'){kindReads=0;assert.equal(integrals.addInterval(2,{admissionViablePendingTasks:pendingTasks,effectiveMaxParallel:1,rootMaxParallel:1,running:0}),true)}reads.push(kindReads)}result.push({candidate:`R09 ${stage}`,n,before:reads[0],after:reads[1],unit:'pending task kind reads'});
 }
 const candidates=Array.from({length:n},(_,i)=>({taskId:`t${i}`,canAdmit:true}));
 let declarationReads=0;
 const activationTaskIds=new Proxy(candidates.map(c=>c.taskId),{get(target,key,receiver){if(typeof key==='string'&&/^\d+$/.test(key))declarationReads++;return Reflect.get(target,key,receiver)}});
 let graphReads=0;
 const publicTasks=graph.schedulerGraphSnapshot.tasks.map(t=>({...t,scopeId:'s'}));
 const publicGraph={...graph.schedulerGraphSnapshot,get tasks(){graphReads++;return publicTasks},scopes:[{id:'s',activationTaskIds,maxParallel:1,terminalTaskId:`t${n-1}`} ]};
 const context:any={graph:publicGraph,candidates,activeScopeIds:[],capacity:{maxParallel:2}};
 declarationReads=0;beforeLayers(context);const beforeActivationReads=declarationReads;
 declarationReads=0;const index=createLearnedSelectionGraph(publicGraph);afterLayers(context,index);const afterActivationReads=declarationReads;
 result.push({candidate:'T02 activation membership',n,before:beforeActivationReads,after:afterActivationReads,unit:'activation indexed reads (including index build)'});
 graphReads=0;for(let i=0;i<n;i++)beforeFallback(context);const beforeGraphReads=graphReads;
 graphReads=0;const fallback=createStaticDecision(publicGraph);for(let i=0;i<n;i++)fallback(context);const afterGraphReads=graphReads;
 result.push({candidate:'T02 repeated fallback',n,before:beforeGraphReads,after:afterGraphReads,unit:'graph task-table reads'});
 const shuffled=candidates.map((c,i)=>({...c,rank:(i*37)%n}));let sortCompares=0,minCompares=0;
 const sorted=[...shuffled].sort((a,b)=>{sortCompares++;return a.rank-b.rank});const first=firstCandidateBy(shuffled,(a:any,b:any)=>{minCompares++;return a.rank-b.rank});assert.equal(first,sorted[0]);
 result.push({candidate:'T02 same comparator first',n,before:sortCompares,after:minCompares,unit:'comparator calls'});
}
// Promise.race's resolved-input preference is not FIFO completion order.
let resolveA!:(value:string)=>void,resolveB!:(value:string)=>void;const a=new Promise<string>(r=>resolveA=r),b=new Promise<string>(r=>resolveB=r);const fifo:string[]=[];void a.then(x=>fifo.push(x));void b.then(x=>fifo.push(x));resolveA('A');await Promise.resolve();resolveB('B');await Promise.resolve();assert.equal(await Promise.race([b,a]),'B');assert.deepEqual(fifo,['A','B']);
console.log(JSON.stringify({baseline:'b2926b14880da7546f39aba7c0e07424f65f3977',runtime:Bun.version,timing:'not measured; operation counts only',result,r06:{race:'B',fifo:'A',adopted:false}},null,2));
// Disjoint direct relation lists are not a dense graph requirement.
for(const n of [16,32,64,128]) {
 const raw=prepareTaskGraph({tasks:[...Array.from({length:2*n},(_,i)=>({id:`r${i}`})),{id:'root',dependsOn:Array.from({length:n},(_,i)=>`r${i}`),observes:Array.from({length:n},(_,i)=>`r${n+i}`)}]});
 const reads=[];
 for(const validate of [beforeValidation,afterValidation]){let count=0;const root=raw.tasks.at(-1)!;const tasks=[...raw.tasks.slice(0,-1),{...root,observes:new Proxy(root.observes,{get(target,key,receiver){if(typeof key==='string'&&/^\d+$/.test(key))count++;return Reflect.get(target,key,receiver)}})}];validate({resourceCapacities:[],rootMaxParallel:1,scopes:[],scopeById:new Map(),tasks,taskById:new Map(tasks.map(t=>[t.id,t]))});reads.push(count)}
 console.error(JSON.stringify({candidate:'R04 disjoint direct overlap',n,before:reads[0],after:reads[1],unit:'observes indexed reads'}));
}
